    <title>الحاسبة الذكية | VSA Academy</title>
    <style>
        :root {
            --bg-color: #0f172a;
            --card-bg: #1e293b;
            --text-color: #f8fafc;
            --accent-color: #38bdf8;
            --accent-hover: #0ea5e9;
            --btn-bg: #334155;
            --btn-hover: #475569;
            --op-bg: #0284c7;
            --op-hover: #0369a1;
            --clear-bg: #ef4444;
            --clear-hover: #dc2626;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
        }

        .calculator {
            background-color: var(--card-bg);
            padding: 24px;
            border-radius: 16px;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
            width: 320px;
            box-sizing: border-box;
        }

        .calculator-header {
            text-align: center;
            margin-bottom: 16px;
            font-size: 1.1rem;
            font-weight: bold;
            color: var(--accent-color);
        }

        .display {
            background-color: #090d16;
            color: #38bdf8;
            font-size: 2rem;
            padding: 16px;
            border-radius: 8px;
            text-align: left;
            margin-bottom: 20px;
            word-wrap: break-word;
            word-break: break-all;
            min-height: 50px;
            box-sizing: border-box;
            direction: ltr;
        }

        .buttons {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 10px;
        }

        button {
            background-color: var(--btn-bg);
            color: var(--text-color);
            border: none;
            padding: 16px;
            font-size: 1.2rem;
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.2s, transform 0.1s;
        }

        button:hover {
            background-color: var(--btn-hover);
        }

        button:active {
            transform: scale(0.95);
        }

        .operator {
            background-color: var(--op-bg);
        }

        .operator:hover {
            background-color: var(--op-hover);
        }

        .clear {
            background-color: var(--clear-bg);
        }

        .clear:hover {
            background-color: var(--clear-hover);
        }

