                    }
                } catch (e) { console.warn("Could not load crypto_alerts.json"); }
            };

            try {
                // محاولة جلب البيانات من Supabase
                const [cardsRes, videosRes, chaptersRes, assetsRes] = await Promise.all([
                    fetch(`${SUPABASE_URL}/rest/v1/cards?select=*`, { headers }),
