        function render(dataArray) {
            const mainGrid = document.getElementById('mainGrid');
            if (!mainGrid) return;

            mainGrid.innerHTML = '';

            if (dataArray.length === 0) {
                if (isDataLoaded) {
                    statusMsg.innerText = "لا توجد بطاقات معروضة في هذا القسم";
