                    `;
                    }
                    else if (type === 'pdf') {
                        // تحديد رابط العرض المناسب
                        let pdfEmbedUrl = url;

                        // Google Drive PDF: تحويل رابط المشاركة إلى رابط معاينة
                        if (url.includes('drive.google.com')) {
